#### **3.2. `grep_simple()`**

```rust
fn grep_simple(search: &str, filename: &str) -> Result<(), Box<dyn std::error::Error>> {
    let file = std::fs::File::open(filename)?;
    let mut content = String::new();
    for line in file.read_lines() {
        content.append(&line);
    }
    content.chunks().enumerate().map(|(i, line)| {
        if grep_str(&search, &line) {
            return Ok((i, line));
        }
    }).next()
}
```

